mapper.update:
UPDATE points_bucket
SET remain = remain - #{amount}, update_time = NOW()
WHERE bucket_id = #{bucketId} AND remain >= #{amount}

mapper.select:
SELECT id, direction, amount, reason_type, ref_id, created_at, expire_at
FROM (
    SELECT id, 'IN' AS direction, amount, reason_type, ref_id, create_time AS created_at, expire_at
    FROM points_bucket
    WHERE user_id = #{userId}
    UNION ALL
    SELECT id, 'OUT' AS direction, amount, reason_type, ref_id, create_time AS created_at, NULL AS expire_at
    FROM points_detail
    WHERE user_id = #{userId}
) merged
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}
